const ROUTE_VIEWS:View[]=["library","suggestions","documents","publications","chat","creations","files","pages","campaigns","analytics","missions","knowledge","projects","billing"];
function getMissionSection(){return typeof window!=='undefined'&&new URL(window.location.href).searchParams.get('section')==='routines'?'routines':'work';}
function getRouteView():View{if(typeof window==="undefined")return"chat";const requested=new URL(window.location.href).searchParams.get("view");return requested&&requested!=="billing"&&requested!=="knowledge"&&ROUTE_VIEWS.includes(requested as View)?requested as View:"chat";}
// Existing bookmarks and payment returns open their section above the conversation.
function getRouteAuth():string|null{if(typeof window==="undefined")return null;const url=new URL(window.location.href);return url.searchParams.get("auth")==="sign-in"?url.searchParams.get("return_to")||"/":null;}
function getRouteSettings():SettingsTab|null{if(typeof window==="undefined")return null;const url=new URL(window.location.href),section=url.searchParams.get("settings");if(isSettingsTab(section))return section;if(url.searchParams.get("view")==="knowledge")return "skills";if(url.pathname==="/pricing"||url.searchParams.get("view")==="billing"||url.searchParams.has("billingOrder"))return "billing";return null;}
function writeSettingsRoute(section:SettingsTab|null){const url=new URL(window.location.href);if(section)url.searchParams.set("settings",section);else{url.searchParams.delete("settings");url.searchParams.delete("billingOrder");if(["billing","knowledge"].includes(url.searchParams.get("view")||""))url.searchParams.delete("view");if(url.pathname==="/pricing")url.pathname="/";}const next=url.pathname+url.search+url.hash;if(next!==location.pathname+location.search+location.hash){window.history.replaceState(null,"",next);window.dispatchEvent(new PopStateEvent("popstate"));}}
function getRoutePricing():boolean{if(typeof window==="undefined")return false;return new URL(window.location.href).searchParams.get("pricing")==="1";}
function writePricingRoute(open:boolean){const url=new URL(window.location.href);if(open)url.searchParams.set("pricing","1");else url.searchParams.delete("pricing");const next=url.pathname+url.search+url.hash;if(next!==location.pathname+location.search+location.hash){window.history.pushState(null,"",next);window.dispatchEvent(new PopStateEvent("popstate"));}}
function subscribeRouteView(onChange:()=>void){window.addEventListener("popstate",onChange);return()=>window.removeEventListener("popstate",onChange);}
